  "pets:cragmaw:combatAbility.name": "Morsure de roc",
  "pets:cragmaw:description": "Un fouisseur aveugle aux mâchoires de pierre qui flaire une gemme dans la roche bien avant que la pioche ne l'atteigne. Au combat, il referme ses mâchoires de granit sur tout ce qui se tient devant lui.",
  "pets:cragmaw:name": "Rocgueule",
  "pets:cragmaw:skillEffect.name": "Flair du filon",
  "pets:flayling:combatAbility.name": "Écorchement",
  "pets:flayling:description": "Elle porte sa propre peau à l'envers et ne semble pas s'en soucier. Peaux et cordons lui passent entre les mains plus vite qu'entre les vôtres. Au combat, elle trouve la faille de chaque armure et la retrousse.",
  "pets:flayling:name": "Écorchon",
  "pets:flayling:skillEffect.name": "Main du tanneur",
  // 1.2.0 „Fasern und Fallen" (Chef 28.08.2026): Begleiter Jagen/Schneidern
  "pets:booted_tomcat:combatAbility.name": "Coup de botte",
  "pets:booted_tomcat:description": "Un matou tigré gris argent aux yeux jaune-vert qui marche debout, bottes aux pieds et harnais de cuir sur le dos, et chasse au collet et à l'arbalète. Aux pièges, avec un peu de chance, il vide le collet deux fois, et une prise laisse dix jets de butin au lieu de cinq. Au combat, il décoche un coup de botte qui laisse l'ennemi boiteux.",
  "pets:booted_tomcat:name": "Leon, le Redouté",
  "pets:booted_tomcat:skillEffect.name": "Double prise",
