  "pets:quillshrike:skillEffect.name": "Double couture",
  "pets:rotbark:combatAbility.name": "Piège de racines",
  "pets:rotbark:description": "Une chose à l'écorce pourrie qui se voûte entre racine et putréfaction. Partout où elle fouille au pied d'un arbre abattu, quelque chose apparaît : un nid d'oiseau, une poignée de graines. Au combat, elle laisse ses racines serpenter et maintient l'ennemi immobile.",
  "pets:rotbark:name": "Écorcepourrie",
  "pets:rotbark:skillEffect.name": "Instinct des racines",
  "pets:slagfiend:combatAbility.name": "Gerbe de scories",
  "pets:slagfiend:name": "Scoriedémon",
  "pets:slagfiend:skillEffect.name": "Bénédiction des braises",
  "pets:sporewretch:combatAbility.name": "Nuage de spores",
  "pets:sporewretch:description": "Une chose voûtée, lourde de moisissure, qui sait où le plus rare se cache sous le commun. Au combat, elle exhale un nuage brun qui fait frapper tout ennemi à côté, l'air hébété.",
  "pets:sporewretch:name": "Sporemisère",
  "pets:sporewretch:skillEffect.name": "Trouvaille de spores",
