  "quests:chronicle_01:name": "La première page",
  "quests:chronicle_02:name": "Premier sang",
  "quests:chronicle_03:name": "L'étincelle dans le grain",
  "quests:chronicle_04:name": "La marche vide",
  "quests:chronicle_05:name": "La bannière de guerre",
  "quests:chronicle_06:name": "La leçon de cendre",
  "quests:chronicle_07:name": "Le roi de la charogne",
  "quests:chronicle_08:name": "Épines",
  "quests:chronicle_09:name": "Le chœur sous les tertres",
  "quests:chronicle_10:name": "Le sceau brisé",
  "quests:chronicle_11:name": "Le seigneur des profondeurs",
  "quests:chronicle_12:name": "Les géants",
  "quests:chronicle_13:name": "La vieille chasse",
  "quests:chronicle_14:name": "Ce que la mer rend",
  "quests:chronicle_15:loreText": "Ici, on fondait toute veine que la terre voulait bien céder, jusqu'à ce minerai dont on coulait les couronnes des images gravées. Je dois ajouter à la Chronique quelque chose que j'ai porté seul toute une vie : je me suis tenu dans ces fonderies, jadis, à la coulée des premières couronnes. Et j'ai vu un homme qui n'en était pas un. Il guidait les mains des fondeurs, et son ombre ne vacillait pas avec le feu. J'ai donné l'alerte. Personne n'écoute un prêtre de dieux silencieux. Alors j'ai commencé à tout consigner. Ce livre n'est pas une chronique, Sans-Nom. C'est le témoignage d'un témoin — tenu contre un accusé sans nom. Maintenant, tu le sais toi aussi.",
  "quests:chronicle_15:name": "La forge froide",
  "quests:chronicle_16:name": "Le ciel mince",
  "quests:chronicle_17:name": "L'aire",
  "quests:chronicle_18:name": "La dernière porte",
  "quests:chronicle_19:name": "Le jugement",
  "quests:chronicle_20:name": "Le vrai coupable",
  "quests:chronicle_21:loreText": "La tour ne se dressait pas là avant que Drazhan ne se retire. Après, elle s'y dressait : son œuvre laissée derrière lui, plus grande que tous les trésors, un terrain d'exercice où la cendre répète tout ce que le Domaine a jamais souffert, étage après étage, plus dur et plus haut. Une répétition pour des armées qui ne marchent pas encore. Le sursis que ta victoire a acheté doit être défendu, et la défense est menée par quiconque grimpe. Je ne grimpe pas. J'attends en bas, le second tome ouvert sur mes genoux, et je consigne les étages comme s'ils étaient des chapitres. Aucun étage sommital n'est connu. Une chose appartient encore au premier tome : parmi les sept couronnes brisées de la chaîne de Drazhan, l'une ne portait aucun nom que les écritures gardent encore. Le ciel resté silencieux si longtemps devra répondre. Les Guerres des Dieux approchent — et la Chronique ne se termine pas. Elle ne fait que gagner un second tome.",
  "quests:chronicle_21:name": "Épilogue : le second tome",
