  // ── New Haven / Encampment (0.3.0, Task #358): 15 Gebäude-Namen + Flavor ──
  "campBuildings:camp_townhall:name": "Maison Commune",
  "campBuildings:camp_townhall:description": "D'abord une cahute avec une table, plus tard une maison avec une cloche : qui l'entend sait qu'à New Haven quelqu'un décide.",
  "campBuildings:camp_watchtower:name": "Tour de guet",
  "campBuildings:camp_watchtower:description": "Tant que quelqu'un veille là-haut, le travail d'en bas ne s'arrête pas.",
  "campBuildings:camp_storehouse:name": "Le Grenier",
  "campBuildings:camp_storehouse:description": "Monté sur pilotis de pierre, pour que ni l'humidité ni les rats n'y entrent. Voss a envoyé le plan, avec l'ordre de tout compter deux fois.",
  "campBuildings:camp_scrivener_tent:name": "La Tente du Scribe",
  "campBuildings:camp_scrivener_tent:description": "Ce qui est écrit le soir n'a plus à être décidé au matin.",
  "campBuildings:camp_fishing_hut:name": "Cabane du pêcheur",
  "campBuildings:camp_fishing_hut:description": "Le gué offre plus qu'un passage, à qui sait rester assis sans bouger.",
  "campBuildings:camp_sawpit:name": "La Fosse de sciage",
  "campBuildings:camp_sawpit:description": "Un homme dessus, un autre dessous dans la sciure ; de toute façon, il en sort des poutres.",
  "campBuildings:camp_mine_adit:name": "La Galerie",
  "campBuildings:camp_mine_adit:description": "Le versant ne donne rien de bon gré, mais il donne.",
  "campBuildings:camp_seed_garden:name": "Le Jardin des semences",
  "campBuildings:camp_seed_garden:description": "Cette terre n'a rien porté de bon depuis longtemps ; on lui réapprend la confiance.",
  "campBuildings:camp_fence_tent:name": "La Tente du Receleur",
  "campBuildings:camp_fence_tent:description": "Personne ne demande d'où vient la marchandise. C'est justement le commerce.",
  "campBuildings:camp_workyard:name": "La Cour des métiers",
  "campBuildings:camp_workyard:description": "Établi contre établi sous une même bâche : chaque métier va plus vite quand le voisin tient les pinces.",
  "campBuildings:camp_smelter:name": "Le Fourneau",
  "campBuildings:camp_smelter:description": "Le feu n'a pas d'horaires : ce qui entre ressort en lingots, qu'on regarde ou non.",
  "campBuildings:camp_smokehouse:name": "Le Fumoir",
  "campBuildings:camp_smokehouse:description": "La fumée est le cuisinier le plus patient du royaume.",
  "campBuildings:camp_trophy_wall:name": "Le Mur aux trophées",
  "campBuildings:camp_trophy_wall:description": "Brenna paie pour des têtes ; le mur se souvient qu'elles ont été livrées.",
  "campBuildings:camp_warden_shrine:name": "Sanctuaire des Silencieux",
  "campBuildings:camp_warden_shrine:description": "Ni image, ni bouche, ni main : seulement une pierre dressée et la chance que quelqu'un écoute.",
  "campBuildings:camp_trade_post:name": "Le Comptoir",
  "campBuildings:camp_trade_post:description": "Mux envoie la charrette dès que la route le permet ; les prix sont justes, dit Mux.",

