  "items:fiber_thornhemp:name": "Chanvre épineux",
  "items:fiber_thornhemp:description": "Fibre grossière d'une haie qui se défend, assez résistante pour dévier le fil d'une lame.",
  "items:fiber_ghostsilk:name": "Soie fantôme",
