  "items:fiber_starflax:name": "Lin stellaire",
  "items:fiber_starflax:description": "Fibre au faible chatoiement froid, comme si elle se souvenait du ciel sous lequel elle a poussé.",
  "items:nettle_seed:name": "Graine d'ortie",
