  "items:kestrel_loop:name": "Anneau de la Crécerelle",
  "items:kestrel_loop:description": "Un anneau fin travaillé avec la plume primaire d'une crécerelle, encore légèrement huileuse de la dernière chasse.",
  "items:hawkeye_gyre:name": "Bandeau de l'Œil de Faucon",
  "items:hawkeye_gyre:description": "Serti d'un éclat de rubis poli, taillé comme l'œil vigilant d'un faucon. Stabilise la main qui tend l'arc.",
  "items:sinewbound_coil:name": "Anneau Lié de Tendon",
  "items:sinewbound_coil:description": "Lié de tendon séché autour d'une pierre sanglante. Ceux qui le portent affirment qu'il vibre faiblement avant que la corde ne se relâche.",
  "items:windwidow_snare:name": "Sceau de la Veuve du Vent",
  "items:windwidow_snare:description": "Nommé d'après une chasseresse qui a survécu à chaque cible qu'elle a jamais visée. Le diamant ne capte jamais tout à fait la lumière de face.",
  "items:blackfletch_nock:name": "Anneau de Plume Noire",
  "items:blackfletch_nock:description": "Onyx serti dans du cuir de guerre, empenné de noir pour disparaître contre un ciel nocturne. La réponse des archers à l'anneau d'onyx des épéistes.",
  "items:ghostquiver_notch:name": "Bandeau du Carquois Fantôme",
  "items:ghostquiver_notch:description": "Enveloppé de peau de dragon pâlie par les années. Ceux qui le portent disent que leur carquois semble plus léger, bien que ce ne soit jamais vrai.",
  "items:worldpiercer_barb:name": "Anneau du Transperce-Monde",
  "items:worldpiercer_barb:description": "Gemme divine sertie dans une peau d'ombre par-dessus un anneau d'éthérium. On dit qu'il a percé d'une flèche quelque chose qui n'aurait pas dû avoir d'autre côté.",
  "items:longsight_cord:name": "Cordon de Longue-Vue",
  "items:longsight_cord:description": "Un cordon de cuir enfilé d'éclats de saphir. Porté par des éclaireurs qui ont appris à faire confiance à leurs yeux avant leurs jambes.",
  "items:windwhisper_torc:name": "Torque du Murmure du Vent",
  "items:windwhisper_torc:description": "Un torque de cuir écaillé serti de rubis. Les cavaliers jurent qu'il porte le son du vol d'une flèche un battement de cœur avant l'impact.",
  "items:harriers_clasp:name": "Chaîne du Faucon Étrangleur",
  "items:harriers_clasp:description": "Cuir clouté enfilé de pierre de sang, nommé d'après un oiseau qui ne rate jamais sa seconde attaque.",
  "items:kitehunter_collar:name": "Pendentif du Chasseur de Milans",
  "items:kitehunter_collar:description": "Diamant serti dans du cuir clouté et du fil de mithril. Reste stable même à pleine course.",
  "items:gloomfletch_choker:name": "Amulette de Plume Sombre",
  "items:gloomfletch_choker:description": "Onyx pris dans un cuir de guerre sombre, empenné de plumes qui semblent boire la lumière alentour. La réponse des archers à l'amulette d'onyx.",
  "items:nightquarry_wreath:name": "Chaîne de la Proie Nocturne",
  "items:nightquarry_wreath:description": "Pierre du néant enroulée dans du cuir de dragon et du fer noirci. Les trophées pris au clair de lune n'ont jamais tout à fait la même allure le jour.",
  "items:deadeye_reliquary:name": "Reliquaire de l'Œil Mortel",
  "items:deadeye_reliquary:description": "Un reliquaire de gemme divine serti dans une peau d'ombre par-dessus de l'éthérium. Il conserve la dernière visée d'une archère qui n'eut jamais besoin d'une seconde flèche.",

