  "items:emberglass_loop:name": "Anneau de Verre-Braise",
  "items:emberglass_loop:description": "Un éclat de feu serti derrière un verre devenu ambré par une vieille chaleur. Réchauffe la main avant même qu'un sort ne soit lancé.",
  "items:hollowlight_seal:name": "Chevalière de Lumière Creuse",
  "items:hollowlight_seal:description": "Un éclat d'aether scellé dans le mithril, luisant faiblement même en plein jour. Le premier anneau dont un mage n'a pas à rougir.",
  "items:nightwell_loop:name": "Anneau du Puits Nocturne",
  "items:nightwell_loop:description": "De l'onyx enroulé autour d'un éclat du néant, tirant sa lueur de quelque chose de plus sombre que le clair de lune. Nommé d'après un puits qu'aucune torche n'a jamais éclairé.",
  "items:voidscribe_glyph:name": "Bracelet du Scribe du Néant",
  "items:voidscribe_glyph:description": "Une pierre du néant gravée d'un glyphe qui se réécrit lui-même dès que personne ne regarde. Ceux qui le portent apprennent à ne pas trop le lire.",
  "items:godsight_loop:name": "Anneau de Vision Divine",
  "items:godsight_loop:description": "Une gemme divine sertie dans un argent béni, censée montrer à son porteur une vérité avant chaque incantation. Peu prétendent aimer ce qu'ils y voient.",
  "items:ashcant_cord:name": "Pendentif du Chant des Cendres",
  "items:gravecall_sigil:name": "Amulette de l'Appel de la Tombe",
  "items:duskveil_wreath:name": "Collier du Voile Crépusculaire",
  "items:duskveil_wreath:description": "De l'onyx enveloppé de runite et de tissu fantôme, censé assombrir un peu la pièce où qu'il soit porté.",
  "items:voidsong_locket:name": "Amulette du Chant du Néant",
  "items:voidsong_locket:description": "Un médaillon de pierre du néant qui fredonne une note que nul autre n'entend. Les lanceurs de sorts jurent qu'il bat exactement au rythme de leur propre pouls.",
  "items:godgem_reliquary:name": "Reliquaire de Gemme Divine",
  "items:godgem_reliquary:description": "Un reliquaire de gemme divine tissé de tissu stellaire, gardant le dernier bouclier d'une lanceuse qui n'en a jamais eu besoin d'un second.",

