  "items:gorecrown_locket:name": "Pendentif de la Couronne Sanglante",
  "items:gorecrown_locket:description": "Une pierre de sang sertie dans de l'acier funéraire par-dessus une peau de guerre, censée se souvenir de chaque bataille dont son porteur est revenu vivant.",
  "items:ironvow_collar:name": "Chaîne du Serment de Fer",
  "items:ironvow_collar:description": "Un diamant lié deux fois de fil de mithril, porté par des guerriers qui ont juré un serment qu'ils comptent bien survivre.",
  "items:reavers_torc:name": "Torque du Pillard",
  "items:reavers_torc:description": "De l'onyx serti deux fois de runite, pris à un pillard qui n'a jamais laissé un ennemi choisir le terrain.",
  "items:bloodiron_locket:name": "Médaillon de Fer Sanglant",
  "items:warcrown_reliquary:name": "Reliquaire de la Couronne de Guerre",
  "items:warcrown_reliquary:description": "Un reliquaire de gemme divine serti deux fois de fer divin, gardant la couronne d'un seigneur de guerre qui n'a jamais eu à la lever pour se défendre.",
  "items:cutthroat_loop:name": "Anneau de l'Égorgeur",
  "items:cutthroat_loop:description": "Un anneau en dents de chacal, porté par des chasseurs qui attendent qu'une blessure s'ouvre avant de frapper. Récompense le coup qui achève tout.",
  "items:firstlight_seal:name": "Chevalière de la Première Lueur",
  "items:firstlight_seal:description": "Forgée dans la première braise d'un feu de forge. Chaque combat se décide au premier coup, ou pas du tout.",
  "items:tidewrack_collar:name": "Chaîne des Épaves de Marée",
  "items:hollowmarch_notch:name": "Bandeau de la Marche Creuse",
  "items:hollowmarch_notch:description": "Poli par une marche sans fin à travers des salles creuses. Se renforce à chaque pas qui ne s'arrête pas.",
  "items:ashenvow_locket:name": "Pendentif du Vœu de Cendres",
  "items:ashenvow_locket:description": "Un vœu juré sur des braises ardentes, tenu même quand la flamme s'est éteinte. Frappe le plus fort avec le dernier souffle dans les poumons.",
  "items:rimeheart_locket:name": "Médaillon de Cœur-de-Givre",
  "items:rimeheart_locket:description": "Gelé de part en part par une mage des glaces qui n'a jamais senti le froid. Punit tout ce qui est déjà trop lent pour fuir.",
  "items:thornwarden_seal:name": "Chevalière du Gardien Épineux",
  "items:thornwarden_seal:description": "Sculptée par un gardien qui transformait chaque coup reçu en le suivant qu'il portait. Récompense le combattant encore debout.",
  "items:sunder_crown:name": "Couronne Brisée",
  "items:sunder_crown:description": "Brisée d'une couronne qui ne régnait sur aucun royaume unique, portée par ceux qui maîtrisent tous les arts à la fois. Un coup fatal frappe plus fort quand il aurait pu venir de n'importe où.",

