  // codex:2026-10-17T15:00:00+02:00 — 1.3.0 E1/E2: offene Götzenhalle, Getilgte Kapelle, Chronik Band 2 Kapitel 22–27 (Texte nach design/lore/band2-auftakt-1.3.0.md §5).
  "monsters:idol_husk:name": "Coque d'idole",
  "monsters:skarn_whelp:name": "Rejeton de Skarn",
  "monsters:forsaken_servant:name": "Serviteur abandonné",
  "monsters:idol_priest:name": "Prêtre de l'idole",
  "monsters:prayer_eater:name": "Mangeur de prières",
  "monsters:wreath_bearer:name": "Porteur de guirlande",
  "monsters:siege_idol:name": "Idole de siège",
  "monsters:the_expunger:name": "L'Effaceur",
  "monsters:dg_wreath_bearer:name": "Porteur de guirlande",
  "monsters:dg_prayer_eater:name": "Mangeur de prières",
  "dungeons:expunged_chapel:name": "La Chapelle effacée",
  "dungeons:expunged_chapel:waveMeta.0.name": "La Procession",
  "dungeons:expunged_chapel:waveMeta.1.name": "La Lacune",
  "dungeons:expunged_chapel:waveMeta.2.name": "L'Effaceur",
  "quests:chronicle_22:name": "La Halle vide",
  "quests:chronicle_23:name": "La Consécration",
  "quests:chronicle_24:name": "Ce que burent les idoles",
  "quests:chronicle_25:name": "Les Guirlandes",
  "quests:chronicle_25:loreText": "Je les ai vus couler, dans la Fosse de Scories, à l'époque où je croyais encore qu'avertir était un métier. Les premières guirlandes de fer divin, guidées par des mains qui n'étaient pas humaines. Les revoici. Les Porteurs de guirlande avancent en procession dans la longue salle, épaule contre épaule, portant ce qu'on leur a posé dessus comme si la procession n'était pas encore finie. Personne ne leur a dit où ils vont. Cela n'a jamais été décidé. Tu t'es mis en travers de leur chemin, et ils sont tombés comme tombent les œuvres : sans plainte, avec beaucoup de bruit. J'ai étudié les bavures de coulée sur les éclats jusqu'à ce que ma main soit calme. On ôte les bavures quand une œuvre est achevée. Celles-ci n'ont jamais été achevées. Cela me soulage d'une manière que je préfère ne pas expliquer.",
  "quests:chronicle_26:name": "Ouvrages de siège",
  "quests:chronicle_26:loreText": "Les idoles étaient ses ouvrages de siège contre le ciel. J'ai noté la phrase quand Drazhan l'a prononcée, et je n'ai compris qu'aujourd'hui qu'il l'entendait au pied de la lettre. Au bout de la Halle, elles se dressent en rang, penchées vers le ciel, les bras refondus en bras de jet, inachevées et sans maître. Ce qu'elles devaient frapper garde le silence. Je préfère que personne ne les achève. Tu les as abattues l'une après l'autre, et quand la dernière s'est couchée, le mur derrière elles était dégagé. Une porte qui ne figure sur aucun plan de la Halle, et j'ai les plans. Au-delà, une aile où chaque inscription a été burinée, proprement, ligne après ligne. Quelqu'un a travaillé ici. Je ne crois pas qu'il ait fini.",
  "quests:chronicle_27:name": "L'Effaceur",
  "quests:chronicle_27:loreText": "La procession à l'entrée, la lacune derrière elle, et au fond de la chapelle : lui. Il n'a pas levé les yeux quand tu es arrivé. Il burinait. L'Effaceur est la main qui a retranché le nom du Septième des écritures, et elle n'a pas cessé de retrancher, car un nom peut revenir si on le laisse faire. Tu l'as abattu, et son œuvre est restée telle quelle : des murs pleins de lacunes, toutes de la même forme. J'en ai suivi une de la main. Elle correspond à la lacune dans laquelle prient les prêtres. Je l'écris sobrement, parce que je ne sais pas l'écrire autrement : le Septième n'a pas été oublié. On le maintient dans l'oubli. Qui le veut ainsi ne figure dans aucun livre que je possède — pas encore. Les Guerres des Dieux ne commencent pas par des dieux. Elles commencent par ce que quelqu'un a voulu effacer.",
  "achievements:ach_chapter_22:name": "La Halle vide",
  "achievements:ach_chapter_23:name": "La Consécration",
  "achievements:ach_chapter_24:name": "Ce que burent les idoles",
  "achievements:ach_chapter_25:name": "Les Guirlandes",
  "achievements:ach_chapter_26:name": "Ouvrages de siège",
  "achievements:ach_chapter_27:name": "Maintenu dans l'oubli",
  "achievements:ach_boss_the_expunger:name": "Fin de l'entaille",
