  "talentNodes:slayer.tracking:flavor": "Brenna lit une piste comme d'autres lisent une lettre.",
  "talentNodes:slayer.trail:flavor": "La malchance finit toujours par s'épuiser. La patience, jamais.",
  "talentNodes:slayer.collar:flavor": "Un collier de plus au crochet près de la porte.",
  "talentNodes:slayer.pace:flavor": "Brenna paie à la tête, et elle compte vite.",
  "talentNodes:slayer.spoils:flavor": "La bête qu'on t'envoie traquer porte toujours sur elle de quoi valoir le voyage.",
  "talentNodes:slayer.lore:flavor": "Quand on a tué chaque espèce, on sait où chacune se brise.",
  // claude:2026-10-18T12:00:00+02:00 — Narbenbuch (Prestige „Der Aschesturz“, Welle B2): Baum, Äste, Knoten.
  "talentTrees:prestige:name": "Livre des Cicatrices",
  "talentTrees:prestige:description": "Le registre du Gardien sur chaque Chute des Cendres. Les cicatrices gagnées à l'Autel des Éclats deviennent ici des dons durables pour chaque partie suivante.",
  "talentBranches:prestige.legacy:name": "Ce qui reste",
  "talentBranches:prestige.haste:name": "Le chemin court",
  "talentBranches:prestige.might:name": "Marqué",
