  // claude:2026-10-30T18:46:25+01:00 — 1.4.2 Narbenbuch (Aschesturz 2.0): Erzählsätze aller Knoten, zwölf neue Knoten mit Name und Wirkung.
  "talentNodes:prestige.startingGold:flavor": "On donne aux morts des pièces pour la route. Tu n'es pas mort, mais les pièces ne gênent pas.",
  "talentNodes:prestige.keepTools:flavor": "Les mains n'oublient pas leurs outils.",
  "talentNodes:prestige.keepPurchases:name": "Comptes soldés",
  "talentNodes:prestige.keepPurchases:description": "Ton palier d'auto-manger, le déblocage de l'amélioration automatique et tous les emplacements de banque achetés survivent à la Chute des Cendres.",
  "talentNodes:prestige.keepPurchases:flavor": "Ce qui est payé reste payé. Même la cendre tient ses comptes.",
  "talentNodes:prestige.keepBankStacks:flavor": "Ce qui était enterré n'a jamais vu le feu.",
  "talentNodes:prestige.keepSlayerPoints:name": "Piste intacte",
  "talentNodes:prestige.keepSlayerPoints:description": "{value} de tes points de Slayer et de tes jetons survivent à la Chute des Cendres.",
  "talentNodes:prestige.keepSlayerPoints:flavor": "Une piste ne refroidit pas simplement parce que le chasseur est tombé.",
  "talentNodes:prestige.keepEquipment:flavor": "Une pièce que la cendre n'aura pas.",
  "talentNodes:prestige.earlyXp:flavor": "Ce qu'on a appris une fois, on le réapprend plus vite.",
  "talentNodes:prestige.chronicleRecall:flavor": "La Chronique ne te relira pas un chapitre déjà vécu.",
  "talentNodes:prestige.dungeonRecall:flavor": "Les portes que tu as franchies une fois te reconnaissent.",
  "talentNodes:prestige.masteredXp:flavor": "Tes mains savent encore où aller.",
