  "talentTrees:slayer:name": "Livre du Slayer",
  "achievements:ach_skill_bowcraft_25:description": "Atteindre le niveau 25 en Archerie.",
  "achievements:ach_skill_bowcraft_50:description": "Atteindre le niveau 50 en Archerie.",
