  "achievements:ach_zone_slagpit_1:description": "Vaincre au moins une fois chaque créature de la Fosse de Scories et des Cavernes de Givre.",
  "achievements:ach_zone_slagpit_100:description": "Vaincre 100 fois chaque créature de la Fosse de Scories et des Cavernes de Givre.",
